const fs = require('fs');
const lines = fs.readFileSync('/tmp/theme-chart.patch', 'utf8').split('\\n');
let i = lines.indexOf('*** Begin Patch') + 1;
while (i < lines.length) {
  const action = lines[i];
  if (action.startsWith('*** Add File: ')) {
    const path = action.slice(14);
    i++;
    const content = [];
    while (i < lines.length && "'!lines[i].startsWith('"'*** ')) {
      if ("'!lines[i].startsWith('"'+')) throw new Error("'`Bad add line: ${lines[i]}`);
      content.push(lines[i].slice(1));
      i++;
    }
    fs.writeFileSync(path, content.join('"'\\n') + '\\n');
  } else if (action.startsWith('*** Update File: ')) {
    const path = action.slice(17);
    i++;
    const old = [];
    const next = [];
    while (i < lines.length && "'!lines[i].startsWith('"'*** ')) {
      if (lines[i].startsWith('-')) old.push(lines[i].slice(1));
      if (lines[i].startsWith('+')) next.push(lines[i].slice(1));
      i++;
    }
    let source = fs.readFileSync(path, 'utf8');
    const oldText = old.join('\\n');
    const newText = next.join('\\n');
    if (oldText.length === 0) {
      source = newText + '\\n';
    } else {
      if ("'!source.includes(oldText)) throw new Error(`No match in ${path}`);
      source = source.replace(oldText, newText);
    }
    fs.writeFileSync(path, source);
  } else {
    throw new Error(`Unsupported patch line: ${action}`);
  }
}
